def get_secret(self, path):
    last_err = None
    for attempt in range(1, self.retries + 1):
        status, body = self.transport("GET", path)
        if status == 200:
            return body
        last_err = f"vault returned {status}"
        if status != 503:
            break
    raise VaultError(last_err or "unreachable")
